import { test, expect } from '@playwright/test';

test.describe('Document Language Declaration', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://yourwebsite.com'); // Replace with your website URL
  });

  test('should have the correct language declared in the HTML tag', async ({ page }) => {
    const htmlTag = await page.locator('html').evaluate(node => node.outerHTML);
    expect(htmlTag).toMatch(/<html lang="en">/); // Replace 'en' with the expected language code
  });

  test('should be accessible with screen readers', async ({ page }) => {
    const langAttribute = await page.locator('html').getAttribute('lang');
    expect(langAttribute).toBe('en'); // Replace 'en' with the expected language code

    // Additional accessibility check can be added here
    const accessibilityCheck = await page.evaluate(() => {
      // Simulate a screen reader check or use an accessibility library
      return true; // Placeholder for actual accessibility check
    });
    expect(accessibilityCheck).toBe(true);
  });
});
